// Turns every tutorial chain listed in tutorials.json into Starlight pages:
// one page per commit with a `Step:` trailer, made from the step's sidecar
// `.tutorial/<number>.mdx`. The components in the sidecar get the repository and
// commit of the step as props, and read the code from git at build time.
//
//   node scripts/sync-tutorials.mjs
//
// Output: src/content/docs/<section>/<number>.mdx (generated, do not edit).
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const siteRoot = process.cwd();
const tutorials = JSON.parse(fs.readFileSync(path.join(siteRoot, 'tutorials.json'), 'utf8'));
const componentsDir = path.join(siteRoot, 'src/components/tutorial');
const tags = ['Snippet', 'Diff', 'Note', 'Demo'];

function git(repo, args) {
  return execFileSync('git', ['-C', repo, ...args], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024, windowsHide: true });
}

for (const t of tutorials) {
  const repo = path.resolve(siteRoot, t.repo);
  const outDir = path.join(siteRoot, 'src/content/docs', t.section);
  fs.rmSync(outDir, { recursive: true, force: true });
  fs.mkdirSync(outDir, { recursive: true });

  // in a fresh clone (e.g. in CI) only the remote branch may exist
  let ref = t.branch;
  try {
    git(repo, ['rev-parse', '--verify', '--quiet', `refs/heads/${t.branch}`]);
  } catch {
    ref = `origin/${t.branch}`;
  }
  const log = git(repo, ['log', '--reverse', '--format=%H%x1f%(trailers:key=Step,valueonly,separator=%x2c)%x1e', ref]);
  const steps = log
    .split('\x1e')
    .map((record) => record.trim())
    .filter(Boolean)
    .map((record) => {
      const [commit, stepId] = record.split('\x1f').map((s) => s.trim());
      return { commit, stepId };
    })
    .filter((s) => s.stepId);

  const seen = new Set();
  const overview = [];
  steps.forEach(({ commit, stepId }, index) => {
    if (seen.has(stepId)) throw new Error(`${t.id}: step ${stepId} appears twice.`);
    seen.add(stepId);
    const number = stepId.split('.').pop();
    let sidecar;
    try {
      sidecar = git(repo, ['show', `${commit}:.tutorial/${number}.mdx`]).replace(/\r\n/g, '\n');
    } catch {
      throw new Error(`${t.id}: step ${stepId} (${commit.slice(0, 7)}) has no .tutorial/${number}.mdx.`);
    }
    const match = sidecar.match(/^---\n([\s\S]*?)\n---\n([\s\S]*)$/);
    if (!match) throw new Error(`${t.id}: .tutorial/${number}.mdx at ${commit.slice(0, 7)} has no frontmatter.`);
    const [, frontmatter, body] = match;
    const title = (frontmatter.match(/^title:\s*(.*)$/m)?.[1] ?? '').replace(/^["']|["']$/g, '');
    overview.push({ number, title, demo: /^demo:\s*true\s*$/m.test(frontmatter) });

    const props = `repo=${JSON.stringify(t.repo)} commit="${commit}" tutorial="${t.id}" step="${number}"`;
    const injected = body.replace(new RegExp(`<(${tags.join('|')})\\b`, 'g'), `<$1 ${props}`);
    const importPath = path.relative(outDir, componentsDir).split(path.sep).join('/');

    const page = [
      '---',
      frontmatter,
      'sidebar:',
      `  order: ${index + 1}`,
      `  label: ${JSON.stringify(`${number} ${title}`)}`,
      `step: "${stepId}"`,
      `commit: "${commit}"`,
      '---',
      `{/* Generated by scripts/sync-tutorials.mjs from ${t.id} ${commit.slice(0, 7)}. Do not edit. */}`,
      `import { ${tags.join(', ')} } from '${importPath}/index.ts';`,
      '',
      injected,
    ].join('\n');
    fs.writeFileSync(path.join(outDir, `${number}.mdx`), page);
  });

  // the tutorial's own page: the list of its steps
  const index = [
    '---',
    `title: ${JSON.stringify(t.label)}`,
    'sidebar:',
    '  order: 0',
    '  label: Overview',
    '---',
    `{/* Generated by scripts/sync-tutorials.mjs from ${t.id}. Do not edit. */}`,
    '',
    ...overview.map((s, i) => `${i + 1}. [${s.title}](/${t.section}/${s.number}/)${s.demo ? ' ▶ demo' : ''}`),
    '',
    `[All steps as slides](/slides/${t.section}/)`,
    '',
  ].join('\n');
  fs.writeFileSync(path.join(outDir, 'index.mdx'), index);
  console.log(`${t.id}: ${steps.length} steps → src/content/docs/${t.section}`);
}
